//! packages/protocol/fixtures/files.json (generated by the TypeScript side):
//! FILE frames byte for byte, the file-name rules, chunk arithmetic, disk
//! levels and the control frames, so runner and gateway cannot drift.

use serde_json::Value;
use tmuxedo_protocol::files::*;

fn fx() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../../packages/protocol/fixtures/files.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture")).expect("json")
}

#[test]
fn file_frames_decode_and_reencode_exactly() {
    let f = fx();
    for c in f["frames"].as_array().unwrap() {
        let name = c["name"].as_str().unwrap();
        let bytes = hex::decode(c["hex"].as_str().unwrap()).unwrap();
        let fr = FileFrame::decode(&bytes).unwrap_or_else(|| panic!("{name}: refused"));
        assert_eq!(fr.id, c["id"].as_str().unwrap(), "{name}");
        assert_eq!(fr.req as u64, c["req"].as_u64().unwrap(), "{name}");
        assert_eq!(fr.offset.to_string(), c["offset"].as_str().unwrap(), "{name}");
        assert_eq!(hex::encode(&fr.payload), c["payloadHex"].as_str().unwrap(), "{name}");
        assert_eq!(hex::encode(fr.encode().unwrap()), c["hex"].as_str().unwrap(), "{name}");
        assert!(is_file_frame(&bytes));
        // A pane stream never mistakes one for pane bytes.
        assert!(tmuxedo_protocol::DataFrame::decode(&bytes).is_none(), "{name}");
    }
    for c in f["invalidFrames"].as_array().unwrap() {
        let bytes = hex::decode(c["hex"].as_str().unwrap()).unwrap();
        assert!(FileFrame::decode(&bytes).is_none(), "{}", c["name"]);
    }
    assert!(FileFrame::decode(&[]).is_none());
    assert!(FileFrame {
        id: "short".into(),
        req: 0,
        offset: 0,
        payload: vec![]
    }
    .encode()
    .is_err());
}

#[test]
fn names_follow_the_shared_rules() {
    for c in fx()["names"].as_array().unwrap() {
        let input = c["in"].as_str().unwrap();
        let want = c["out"].as_str().map(str::to_owned);
        assert_eq!(sanitize_name(input), want, "{input:?}");
    }
}

#[test]
fn chunks_disk_and_stamps() {
    let f = fx();
    for c in f["chunks"].as_array().unwrap() {
        let (size, cs) = (c["size"].as_u64().unwrap(), c["chunkSize"].as_u64().unwrap());
        let count = c["count"].as_u64().unwrap();
        assert_eq!(chunk_count(size, cs), count);
        let as_i = |v: Option<u64>| v.map(|x| x as i64).unwrap_or(-1);
        assert_eq!(as_i(chunk_len(size, cs, 0)), c["first"].as_i64().unwrap());
        assert_eq!(
            as_i(count.checked_sub(1).and_then(|l| chunk_len(size, cs, l))),
            c["last"].as_i64().unwrap()
        );
        assert_eq!(as_i(chunk_len(size, cs, count)), c["beyond"].as_i64().unwrap());
    }
    for c in f["disk"].as_array().unwrap() {
        let (free, total) = (c["freeBytes"].as_u64().unwrap(), c["totalBytes"].as_u64().unwrap());
        assert_eq!(disk_level(free, total), c["level"].as_str().unwrap(), "{c}");
        assert_eq!(free_space_floor(total), c["floor"].as_u64().unwrap(), "{c}");
    }
    let at = f["stamp"]["at"].as_str().unwrap();
    // 2026-10-03T14:02:11.123Z in ms
    assert_eq!(at, "2026-10-03T14:02:11.123Z");
    assert_eq!(upload_stamp(1_791_036_131_123), f["stamp"]["stamp"].as_str().unwrap());
}

#[test]
fn control_frames_both_ways() {
    let f = fx();
    for g in f["control"]["gatewayToRunner"].as_array().unwrap() {
        let parsed = FileCtl::parse(&g.to_string()).unwrap_or_else(|| panic!("{g}"));
        let back: Value = serde_json::to_value(&parsed).unwrap();
        assert_eq!(&back, g);
    }
    for r in f["control"]["runnerToGateway"].as_array().unwrap() {
        let v: Value = match r["t"].as_str().unwrap() {
            "file_ack" => serde_json::to_value(serde_json::from_value::<FileAck>(r.clone()).unwrap()).unwrap(),
            "disk" => {
                let d = DiskFrame::new(
                    r["freeBytes"].as_u64().unwrap(),
                    r["totalBytes"].as_u64().unwrap(),
                    r["filesBytes"].as_u64().unwrap(),
                );
                serde_json::from_str(&d.to_json()).unwrap()
            }
            t => panic!("{t}"),
        };
        assert_eq!(&v, r);
    }
    let ok: Value = serde_json::from_str(&FileAck::ok("up_0123456789abcdef", 3, &"a".repeat(64)).to_json()).unwrap();
    assert_eq!(ok, f["control"]["runnerToGateway"][0]);
}
